//! `cargo run -p viewer-content-api --example generate_rdb_header [output path]`
//!
//! the default output is `rdb.h` next to the `bindings.h` generated by the build script.

fn main() {
  let path = std::env::args()
    .nth(1)
    .unwrap_or_else(|| concat!(env!("CARGO_MANIFEST_DIR"), "/rdb.h").to_string());
  std::fs::write(&path, viewer_content_api::generate_rdb_header()).unwrap();
  println!("rdb header is written to {path}");
}
